import type { Metadata } from "next";

// Overlay URLs are bearer secrets intended for OBS, never search results.
export const metadata: Metadata = {
  robots: { index: false, follow: false, noarchive: true },
};

export default function OverlayLayout({ children }: { children: React.ReactNode }) {
  // The overlay font faces are self-hosted in public/fonts/fonts.css (generated by
  // scripts/fetch-fonts.ts): @font-face is lazy, so only the families a theme actually uses
  // get downloaded, from the worker's edge-cached static assets rather than Google's CDN,
  // which the enforcing CSP would refuse anyway. Loaded here and by the Theme Center page —
  // the two surfaces that render overlay content — not by the root layout, so the landing,
  // dashboard and bot pages skip it. React hoists and dedupes the link.
  // The base layer paints <body> with the theme background; overlays must be
  // transparent on their own, not only when OBS injects its default custom CSS
  // (and in the dashboard's preview iframes, which never get it).
  return (
    <>
      <link rel="stylesheet" href="/fonts/fonts.css" precedence="default" />
      <style>{"html,body{background:transparent!important}"}</style>
      {children}
    </>
  );
}
